<?php declare(strict_types=1);require_once __DIR__.'/../includes/auth_check.php';require_once __DIR__.'/../includes/functions.php';$id=0;$editing=false;$record=['author_name'=>'','country'=>''];if($editing){$s=$pdo->prepare('SELECT * FROM authors WHERE author_id=?');$s->execute([$id]);$record=$s->fetch();if(!$record){set_flash('error','Record not found.');redirect('/authors/index.php');}}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf_token($_POST['csrf_token']??null))$error='Session expired. Refresh and try again.';else{$name=trim($_POST['author_name']??'');$other=trim($_POST['country']??'');if($name==='')$error='Name is required.';else{try{if($editing){$s=$pdo->prepare('UPDATE authors SET author_name=?,country=? WHERE author_id=?');$s->execute([$name,$other?:null,$id]);}else{$s=$pdo->prepare('INSERT INTO authors(author_name,country) VALUES(?,?)');$s->execute([$name,$other?:null]);}set_flash('success','Record saved.');redirect('/authors/index.php');}catch(PDOException $e){$error='This name may already exist or the record is linked to another item.';}}}}$pageTitle=$editing?'Edit author':'Add author';$activePage='authors';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/navbar.php';?>
